//! Private Fabric node daemon.
//!
//! Runs on customer-owned or Allternit-managed hardware. It enrolls with the
//! control plane, heartbeats capacity, polls for assignments, and executes
//! workloads locally. This first slice implements enrollment, heartbeat, and
//! assignment polling; actual workload execution is delegated to the local
//! substrate (Incus, process runner, etc.) in later iterations.
//!
//! Environment variables:
//! - `FABRIC_NODE_CONTROL_PLANE` — base URL of the Allternit API (required).
//! - `FABRIC_NODE_ENROLLMENT_TOKEN` — enrollment token generated by the control
//!   plane (required).
//! - `FABRIC_NODE_REGION` — region label, e.g. `us-east` (default: `any`).
//! - `FABRIC_NODE_DISPLAY_NAME` — human-readable name (default: hostname).
//! - `FABRIC_NODE_HEARTBEAT_SECONDS` — heartbeat interval (default: 30).

use allternit_computer_cloud::providers::fabric_node::NodeCapacity;
use async_trait::async_trait;
use chrono::Utc;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::Duration;
use tokio::process::Command;
use tracing::{info, warn};

const DEFAULT_HEARTBEAT_SECONDS: u64 = 30;

#[derive(Clone, Debug)]
struct Config {
    control_plane: String,
    enrollment_token: String,
    node_token: Option<String>,
    node_token_file: Option<String>,
    region: String,
    display_name: String,
    heartbeat_interval: Duration,
}

impl Config {
    fn from_env() -> Result<Self, String> {
        let control_plane = std::env::var("FABRIC_NODE_CONTROL_PLANE")
            .map_err(|_| "FABRIC_NODE_CONTROL_PLANE is required".to_string())?;
        if control_plane.is_empty() {
            return Err("FABRIC_NODE_CONTROL_PLANE must not be empty".to_string());
        }

        let enrollment_token = std::env::var("FABRIC_NODE_ENROLLMENT_TOKEN")
            .map_err(|_| "FABRIC_NODE_ENROLLMENT_TOKEN is required".to_string())?;
        if enrollment_token.is_empty() {
            return Err("FABRIC_NODE_ENROLLMENT_TOKEN must not be empty".to_string());
        }

        let node_token_file = std::env::var("FABRIC_NODE_TOKEN_FILE").ok();
        let node_token = node_token_file
            .as_ref()
            .and_then(|path| std::fs::read_to_string(path).ok())
            .filter(|s| !s.trim().is_empty());

        let region = std::env::var("FABRIC_NODE_REGION").unwrap_or_else(|_| "any".to_string());
        let display_name = std::env::var("FABRIC_NODE_DISPLAY_NAME")
            .unwrap_or_else(|_| default_hostname());

        let heartbeat_seconds = std::env::var("FABRIC_NODE_HEARTBEAT_SECONDS")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(DEFAULT_HEARTBEAT_SECONDS);

        Ok(Self {
            control_plane,
            enrollment_token,
            node_token,
            node_token_file,
            region,
            display_name,
            heartbeat_interval: Duration::from_secs(heartbeat_seconds),
        })
    }
}

fn default_hostname() -> String {
    std::env::var("HOSTNAME")
        .ok()
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "fabric-node".to_string())
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct EnrollRequest {
    display_name: String,
    region: String,
    capacity: NodeCapacity,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct EnrollResponse {
    node_id: String,
    status: String,
    node_token: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct HeartbeatRequest {
    measured_at: chrono::DateTime<Utc>,
    capacity: NodeCapacity,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct HeartbeatResponse {
    status: String,
    #[serde(default)]
    assignments: Vec<Assignment>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Assignment {
    assignment_id: String,
    resource_id: String,
    kind: String,
    class: String,
    payload: Option<serde_json::Value>,
}

/// Result of executing an assignment locally.
#[derive(Debug, Clone)]
struct ExecutionOutcome {
    exit_code: i32,
    stdout: String,
    stderr: String,
}

#[derive(Debug, Clone)]
enum ExecutionError {
    Unsupported(String),
    Spawn(String),
}

impl std::fmt::Display for ExecutionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ExecutionError::Unsupported(msg) => write!(f, "unsupported assignment: {msg}"),
            ExecutionError::Spawn(msg) => write!(f, "failed to spawn: {msg}"),
        }
    }
}

#[async_trait]
trait AssignmentExecutor: Send + Sync {
    async fn execute(&self, assignment: &Assignment) -> Result<ExecutionOutcome, ExecutionError>;
}

/// Default executor that runs assignments as local shell commands.
///
/// If the assignment payload contains a `command` string, that command is run
/// directly. Otherwise a small default command is chosen from the assignment
/// kind/class. This is intentionally lightweight: Private Fabric nodes can run
/// real workloads without requiring Incus or another container runtime.
#[derive(Debug, Clone, Default)]
struct ProcessExecutor;

fn build_command(assignment: &Assignment) -> String {
    if let Some(payload) = &assignment.payload {
        if let Some(cmd) = payload.get("command").and_then(|v| v.as_str()) {
            return cmd.to_string();
        }
    }
    match (assignment.kind.as_str(), assignment.class.as_str()) {
        ("compute", "s") => "echo 'compute.s started'; sleep 5; echo 'compute.s done'".to_string(),
        ("compute", "m") => "echo 'compute.m started'; sleep 5; echo 'compute.m done'".to_string(),
        ("compute", "l") => "echo 'compute.l started'; sleep 5; echo 'compute.l done'".to_string(),
        ("sandbox", "s") => "echo 'sandbox.s started'; sleep 5; echo 'sandbox.s done'".to_string(),
        ("gpu", "s") => "echo 'gpu.s started'; sleep 5; echo 'gpu.s done'".to_string(),
        ("agent", _) => "echo 'agent started'; sleep 5; echo 'agent done'".to_string(),
        ("batch", _) => "echo 'batch started'; sleep 5; echo 'batch done'".to_string(),
        _ => format!("echo 'unsupported kind={} class={}'", assignment.kind, assignment.class),
    }
}

#[async_trait]
impl AssignmentExecutor for ProcessExecutor {
    async fn execute(&self, assignment: &Assignment) -> Result<ExecutionOutcome, ExecutionError> {
        let command = build_command(assignment);
        let output = Command::new("sh")
            .arg("-c")
            .arg(command)
            .output()
            .await
            .map_err(|e| ExecutionError::Spawn(e.to_string()))?;
        Ok(ExecutionOutcome {
            exit_code: output.status.code().unwrap_or(-1),
            stdout: String::from_utf8_lossy(&output.stdout).to_string(),
            stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        })
    }
}

#[derive(Clone)]
struct Daemon {
    config: Config,
    http: reqwest::Client,
    node_id: Option<String>,
    node_token: Option<String>,
    executor: Arc<dyn AssignmentExecutor>,
}

impl std::fmt::Debug for Daemon {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Daemon")
            .field("config", &self.config)
            .field("node_id", &self.node_id)
            .field("node_token", &"<redacted>")
            .field("executor", &"<dyn AssignmentExecutor>")
            .finish_non_exhaustive()
    }
}

impl Daemon {
    fn new(config: Config) -> Self {
        Self::with_executor(config, Arc::new(ProcessExecutor))
    }

    fn with_executor(config: Config, executor: Arc<dyn AssignmentExecutor>) -> Self {
        Self {
            node_token: config.node_token.clone(),
            config,
            http: reqwest::Client::new(),
            node_id: None,
            executor,
        }
    }

    fn base_url(&self) -> String {
        self.config.control_plane.trim_end_matches('/').to_string()
    }

    fn auth_header(&self) -> String {
        let token = self
            .node_token
            .as_deref()
            .unwrap_or(&self.config.enrollment_token);
        format!("Bearer {}", token)
    }

    fn persist_node_token(&self, token: &str) {
        if let Some(path) = &self.config.node_token_file {
            if let Err(e) = std::fs::write(path, token) {
                warn!(path, error = %e, "failed to persist node token");
            } else {
                info!(path, "persisted node token");
            }
        }
    }

    async fn enroll(&mut self) -> Result<String, String> {
        let capacity = detect_capacity();
        let req = EnrollRequest {
            display_name: self.config.display_name.clone(),
            region: self.config.region.clone(),
            capacity,
        };

        let url = format!("{}/v1/fabric/nodes/enroll", self.base_url());
        let res = self
            .http
            .post(&url)
            .header("Authorization", self.auth_header())
            .json(&req)
            .send()
            .await
            .map_err(|e| format!("enrollment request failed: {e}"))?;

        if !res.status().is_success() {
            let body = res
                .text()
                .await
                .unwrap_or_else(|_| "<unreadable>".to_string());
            return Err(format!("enrollment failed: {body}"));
        }

        let body: EnrollResponse = res
            .json()
            .await
            .map_err(|e| format!("enrollment response parse failed: {e}"))?;

        info!(node_id = %body.node_id, status = %body.status, "enrolled with control plane");
        self.node_id = Some(body.node_id.clone());
        self.node_token = Some(body.node_token.clone());
        self.persist_node_token(&body.node_token);
        Ok(body.node_id)
    }

    async fn heartbeat(&self) -> Result<Vec<Assignment>, String> {
        let node_id = self
            .node_id
            .as_ref()
            .ok_or("node has not enrolled yet")?;

        let capacity = detect_capacity();
        let req = HeartbeatRequest {
            measured_at: Utc::now(),
            capacity,
        };

        let url = format!("{}/v1/fabric/nodes/{}/heartbeat", self.base_url(), node_id);
        let res = self
            .http
            .post(&url)
            .header("Authorization", self.auth_header())
            .json(&req)
            .send()
            .await
            .map_err(|e| format!("heartbeat request failed: {e}"))?;

        if !res.status().is_success() {
            let body = res.text().await.unwrap_or_else(|_| "<unreadable>".to_string());
            return Err(format!("heartbeat failed: {body}"));
        }

        let body: HeartbeatResponse = res
            .json()
            .await
            .map_err(|e| format!("heartbeat response parse failed: {e}"))?;

        Ok(body.assignments)
    }

    async fn ack_assignment(&self, assignment_id: &str, status: &str) -> Result<(), String> {
        let node_id = self
            .node_id
            .as_ref()
            .ok_or("node has not enrolled yet")?;

        let url = format!(
            "{}/v1/fabric/nodes/{}/assignments/{}/status",
            self.base_url(),
            node_id,
            assignment_id
        );
        let req = serde_json::json!({"status": status});
        let res = self
            .http
            .post(&url)
            .header("Authorization", self.auth_header())
            .json(&req)
            .send()
            .await
            .map_err(|e| format!("assignment ack request failed: {e}"))?;

        if !res.status().is_success() {
            let body = res.text().await.unwrap_or_else(|_| "<unreadable>".to_string());
            return Err(format!("assignment ack failed: {body}"));
        }

        info!(assignment_id, status, "acknowledged assignment");
        Ok(())
    }

    async fn run_loop(&self) {
        loop {
            self.run_once().await;
            tokio::time::sleep(self.config.heartbeat_interval).await;
        }
    }

    /// Poll one heartbeat and handle any returned assignments.
    async fn run_once(&self) {
        match self.heartbeat().await {
            Ok(assignments) => {
                if !assignments.is_empty() {
                    info!(count = assignments.len(), "received assignments");
                    for a in assignments {
                        self.handle_assignment(a).await;
                    }
                }
            }
            Err(e) => {
                warn!(error = %e, "heartbeat failed");
            }
        }
    }

    /// Full assignment lifecycle: acknowledge, execute, report final state, and
    /// submit a usage event.
    async fn handle_assignment(&self, assignment: Assignment) {
        info!(assignment_id = %assignment.assignment_id, kind = %assignment.kind, "handling assignment");

        if let Err(e) = self.ack_assignment(&assignment.assignment_id, "accepted").await {
            warn!(assignment_id = %assignment.assignment_id, error = %e, "failed to ack assignment accepted");
            return;
        }

        if let Err(e) = self.ack_assignment(&assignment.assignment_id, "running").await {
            warn!(assignment_id = %assignment.assignment_id, error = %e, "failed to mark assignment running");
            return;
        }

        let start = std::time::Instant::now();
        let (final_status, outcome) = match self.executor.execute(&assignment).await {
            Ok(result) => {
                info!(
                    assignment_id = %assignment.assignment_id,
                    exit_code = result.exit_code,
                    "assignment executed"
                );
                if result.exit_code == 0 {
                    ("completed", Some(result))
                } else {
                    ("failed", Some(result))
                }
            }
            Err(e) => {
                warn!(assignment_id = %assignment.assignment_id, error = %e, "assignment execution failed");
                ("failed", None)
            }
        };

        if let Err(e) = self.ack_assignment(&assignment.assignment_id, final_status).await {
            warn!(
                assignment_id = %assignment.assignment_id,
                error = %e,
                "failed to mark assignment {}",
                final_status
            );
            return;
        }

        let seconds = start.elapsed().as_secs_f64();
        info!(
            assignment_id = %assignment.assignment_id,
            status = final_status,
            seconds,
            "assignment lifecycle complete"
        );

        if let Some(outcome) = outcome {
            let stdout = outcome.stdout.trim();
            let stderr = outcome.stderr.trim();
            if !stdout.is_empty() {
                info!(assignment_id = %assignment.assignment_id, stdout, "assignment stdout");
            }
            if !stderr.is_empty() {
                warn!(assignment_id = %assignment.assignment_id, stderr, "assignment stderr");
            }
        }

        if let Err(e) = self.submit_usage(&assignment.resource_id, seconds).await {
            warn!(assignment_id = %assignment.assignment_id, error = %e, "failed to submit usage");
        }
    }

    async fn submit_usage(&self, resource_id: &str, seconds: f64) -> Result<(), String> {
        let node_id = self
            .node_id
            .as_ref()
            .ok_or("node has not enrolled yet")?;

        let url = format!("{}/v1/fabric/nodes/{}/usage", self.base_url(), node_id);
        let req = serde_json::json!({
            "resource_id": resource_id,
            "event_type": "compute_seconds",
            "quantity": seconds,
            "unit": "seconds",
            "measured_at": Utc::now().to_rfc3339(),
        });
        let res = self
            .http
            .post(&url)
            .header("Authorization", self.auth_header())
            .json(&req)
            .send()
            .await
            .map_err(|e| format!("usage submit request failed: {e}"))?;

        if !res.status().is_success() {
            let body = res.text().await.unwrap_or_else(|_| "<unreadable>".to_string());
            return Err(format!("usage submit failed: {body}"));
        }

        info!(resource_id, seconds, "submitted usage event");
        Ok(())
    }
}

/// Best-effort capacity detection. In production this reads /proc, cgroups,
/// nvml, etc. The skeleton reports vCPU count and a memory default that can be
/// overridden with `FABRIC_NODE_MEMORY_MIB`.
fn detect_capacity() -> NodeCapacity {
    let total_memory_mib = std::env::var("FABRIC_NODE_MEMORY_MIB")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(8192);
    let total_vcpu = std::thread::available_parallelism()
        .map(|n| n.get() as u32)
        .unwrap_or(4);

    NodeCapacity {
        total_vcpu,
        total_memory_mib,
        total_gpu_vram_mib: 0,
        gpu_model: None,
        free_vcpu: total_vcpu,
        free_memory_mib: total_memory_mib,
        free_gpu_vram_mib: 0,
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt::init();

    let config = match Config::from_env() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("configuration error: {e}");
            std::process::exit(1);
        }
    };

    let mut daemon = Daemon::new(config);
    match daemon.enroll().await {
        Ok(node_id) => {
            info!(node_id = %node_id, "fabric node daemon running");
            daemon.run_loop().await;
        }
        Err(e) => {
            eprintln!("enrollment error: {e}");
            std::process::exit(1);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn test_config(server_url: String) -> Config {
        Config {
            control_plane: server_url,
            enrollment_token: "test-token".to_string(),
            node_token: None,
            node_token_file: None,
            region: "us-east".to_string(),
            display_name: "test-node".to_string(),
            heartbeat_interval: Duration::from_secs(1),
        }
    }

    #[derive(Debug, Clone)]
    struct MockExecutor {
        outcome: Arc<std::sync::Mutex<Result<ExecutionOutcome, ExecutionError>>>,
    }

    impl MockExecutor {
        fn new(outcome: Result<ExecutionOutcome, ExecutionError>) -> Self {
            Self {
                outcome: Arc::new(std::sync::Mutex::new(outcome)),
            }
        }
    }

    #[async_trait]
    impl AssignmentExecutor for MockExecutor {
        async fn execute(&self, _assignment: &Assignment) -> Result<ExecutionOutcome, ExecutionError> {
            self.outcome.lock().unwrap().clone()
        }
    }

    fn success_outcome(stdout: &str) -> ExecutionOutcome {
        ExecutionOutcome {
            exit_code: 0,
            stdout: stdout.to_string(),
            stderr: String::new(),
        }
    }

    fn failure_outcome() -> ExecutionOutcome {
        ExecutionOutcome {
            exit_code: 1,
            stdout: String::new(),
            stderr: "error".to_string(),
        }
    }

    #[tokio::test]
    async fn daemon_enrolls_and_heartbeats() {
        let mut server = mockito::Server::new_async().await;
        let mut daemon = Daemon::new(test_config(server.url()));

        server
            .mock("POST", "/v1/fabric/nodes/enroll")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"node_id":"node-1","status":"pending","node_token":"node-token-1"}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-1/heartbeat")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"status":"active","assignments":[]}"#)
            .create_async()
            .await;

        let node_id = daemon.enroll().await.unwrap();
        assert_eq!(node_id, "node-1");

        let assignments = daemon.heartbeat().await.unwrap();
        assert!(assignments.is_empty());
    }

    #[tokio::test]
    async fn heartbeat_returns_assignments() {
        let mut server = mockito::Server::new_async().await;
        let mut daemon = Daemon::new(test_config(server.url()));

        server
            .mock("POST", "/v1/fabric/nodes/enroll")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"node_id":"node-2","status":"active","node_token":"node-token-2"}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-2/heartbeat")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"status":"active","assignments":[{"assignment_id":"a1","resource_id":"r1","kind":"compute","class":"s","payload":null}]}"#)
            .create_async()
            .await;

        daemon.enroll().await.unwrap();
        let assignments = daemon.heartbeat().await.unwrap();
        assert_eq!(assignments.len(), 1);
        assert_eq!(assignments[0].assignment_id, "a1");
    }

    #[tokio::test]
    async fn daemon_acks_assignment() {
        let mut server = mockito::Server::new_async().await;
        let mut daemon = Daemon::new(test_config(server.url()));

        server
            .mock("POST", "/v1/fabric/nodes/enroll")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"node_id":"node-3","status":"active","node_token":"node-token-3"}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-3/assignments/a2/status")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"assignment_id":"a2","status":"accepted"}"#)
            .create_async()
            .await;

        daemon.enroll().await.unwrap();
        daemon.ack_assignment("a2", "accepted").await.unwrap();
    }

    #[tokio::test]
    async fn daemon_runs_assignment_and_reports_completed() {
        let mut server = mockito::Server::new_async().await;
        let executor = Arc::new(MockExecutor::new(Ok(success_outcome("done"))));
        let mut daemon = Daemon::with_executor(test_config(server.url()), executor);

        server
            .mock("POST", "/v1/fabric/nodes/enroll")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"node_id":"node-4","status":"active","node_token":"node-token-4"}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-4/heartbeat")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"status":"active","assignments":[{"assignment_id":"a3","resource_id":"r3","kind":"compute","class":"s","payload":{"command":"echo done"}}]}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-4/assignments/a3/status")
            .match_body(mockito::Matcher::JsonString(r#"{"status":"accepted"}"#.to_string()))
            .with_status(200)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-4/assignments/a3/status")
            .match_body(mockito::Matcher::JsonString(r#"{"status":"running"}"#.to_string()))
            .with_status(200)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-4/assignments/a3/status")
            .match_body(mockito::Matcher::JsonString(r#"{"status":"completed"}"#.to_string()))
            .with_status(200)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-4/usage")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"status":"recorded"}"#)
            .create_async()
            .await;

        daemon.enroll().await.unwrap();
        daemon.run_once().await;
    }

    #[tokio::test]
    async fn daemon_reports_failed_execution() {
        let mut server = mockito::Server::new_async().await;
        let executor = Arc::new(MockExecutor::new(Ok(failure_outcome())));
        let mut daemon = Daemon::with_executor(test_config(server.url()), executor);

        server
            .mock("POST", "/v1/fabric/nodes/enroll")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"node_id":"node-5","status":"active","node_token":"node-token-5"}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-5/heartbeat")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"status":"active","assignments":[{"assignment_id":"a4","resource_id":"r4","kind":"compute","class":"s","payload":{"command":"exit 1"}}]}"#)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-5/assignments/a4/status")
            .match_body(mockito::Matcher::JsonString(r#"{"status":"accepted"}"#.to_string()))
            .with_status(200)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-5/assignments/a4/status")
            .match_body(mockito::Matcher::JsonString(r#"{"status":"running"}"#.to_string()))
            .with_status(200)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-5/assignments/a4/status")
            .match_body(mockito::Matcher::JsonString(r#"{"status":"failed"}"#.to_string()))
            .with_status(200)
            .create_async()
            .await;

        server
            .mock("POST", "/v1/fabric/nodes/node-5/usage")
            .with_status(200)
            .with_header("content-type", "application/json")
            .with_body(r#"{"status":"recorded"}"#)
            .create_async()
            .await;

        daemon.enroll().await.unwrap();
        daemon.run_once().await;
    }

    #[tokio::test]
    async fn process_executor_runs_payload_command() {
        let assignment = Assignment {
            assignment_id: "a5".to_string(),
            resource_id: "r5".to_string(),
            kind: "compute".to_string(),
            class: "s".to_string(),
            payload: Some(serde_json::json!({"command": "echo hello-world"})),
        };
        let executor = ProcessExecutor;
        let outcome = executor.execute(&assignment).await.unwrap();
        assert_eq!(outcome.exit_code, 0);
        assert!(outcome.stdout.contains("hello-world"));
    }
}
